import {ActionList, Button, Dialog, TextInput} from '@primer/react'
import {FileCodeIcon, SearchIcon} from '@primer/octicons-react'
import {useState} from 'react'
import styles from './CodeCoverageWorkflowDialog.module.css'
import type {WorkflowFile} from './code-coverage-types'

interface CodeCoverageWorkflowDialogProps {
  open: boolean
  onClose: () => void
  existingWorkflowFiles: WorkflowFile[]
  newWorkflowUrl: string
}

export function CodeCoverageWorkflowDialog({
  open,
  onClose,
  existingWorkflowFiles,
  newWorkflowUrl,
}: CodeCoverageWorkflowDialogProps) {
  const [selected, setSelected] = useState<string>(existingWorkflowFiles[0]?.editUrl ?? '')
  const [search, setSearch] = useState('')

  if (!open) return null

  const filteredFiles = existingWorkflowFiles.filter(f => (f.name ?? '').toLowerCase().includes(search.toLowerCase()))
  const isSelectedVisible = filteredFiles.some(f => f.editUrl === selected)

  const handleApply = () => {
    if (selected) {
      window.open(selected, '_blank', 'noopener,noreferrer')
    }
    onClose()
  }

  const handleCreateNew = () => {
    window.open(newWorkflowUrl, '_blank', 'noopener,noreferrer')
    onClose()
  }

  return (
    <Dialog onClose={onClose} title="Select a workflow" width="large" height="large">
      <Dialog.Body>
        <p className="color-fg-muted mb-3">
          Select an existing workflow or create a new one in your repository as a configuration for testing the code
          coverage.
        </p>
        <TextInput
          leadingVisual={SearchIcon}
          placeholder="Search"
          aria-label="Search workflows"
          value={search}
          onChange={e => setSearch(e.target.value)}
          block
          className="mb-3"
        />
        <ActionList selectionVariant="radio" showDividers aria-label="Workflow files" className={styles.workflowList}>
          {filteredFiles.map(file => {
            const isSelected = selected === file.editUrl
            return (
              <ActionList.Item
                key={file.editUrl}
                selected={isSelected}
                onSelect={() => setSelected(file.editUrl)}
                className={`${styles.workflowRow} ${isSelected ? styles.workflowRowSelected : ''}`}
              >
                <ActionList.LeadingVisual>
                  <FileCodeIcon />
                </ActionList.LeadingVisual>
                {file.name}
              </ActionList.Item>
            )
          })}
        </ActionList>
        {filteredFiles.length === 0 && (
          <p role="status" className="color-fg-muted p-3 text-center">
            No workflows found
          </p>
        )}
      </Dialog.Body>
      <Dialog.Footer className="border-top color-border-default">
        <Button onClick={handleCreateNew} className="mr-auto">
          Create new workflow
        </Button>
        <Button onClick={onClose}>Cancel</Button>
        <Button variant="primary" onClick={handleApply} disabled={!selected || !isSelectedVisible}>
          Apply
        </Button>
      </Dialog.Footer>
    </Dialog>
  )
}
