import {ActionList, ActionMenu, Button, Heading, Link, Spinner} from '@primer/react'
import {CopilotIcon, FileCodeIcon, WorkflowIcon} from '@primer/octicons-react'
import type {ReactNode} from 'react'
import {useState} from 'react'
import {CodeCoverageWorkflowDialog} from './CodeCoverageWorkflowDialog'
import type {WorkflowFile} from './code-coverage-types'

const COVERAGE_FILE_PATTERN = /^code-coverage(\d+)?\.yml$/

function basename(filePath: string): string {
  return filePath.split('/').pop() ?? filePath
}

function isCoverageFile(f: WorkflowFile): boolean {
  return basename(f.editUrl).includes('code-coverage')
}

function getHighestCoverageFile(workflowFiles: WorkflowFile[]): WorkflowFile | undefined {
  const files = workflowFiles.filter(isCoverageFile)
  if (files.length === 0) return undefined
  return files.reduce((best, f) => {
    const bestNum = parseInt(COVERAGE_FILE_PATTERN.exec(basename(best.editUrl))?.[1] ?? '0', 10)
    const fNum = parseInt(COVERAGE_FILE_PATTERN.exec(basename(f.editUrl))?.[1] ?? '0', 10)
    return fNum > bestNum ? f : best
  })
}

export function getNextCoverageFilename(workflowFiles: WorkflowFile[]): string {
  const basenames = new Set(workflowFiles.map(f => basename(f.editUrl)).filter((n): n is string => !!n))
  if (!basenames.has('code-coverage.yml')) return 'code-coverage.yml'
  let max = 1
  for (const name of basenames) {
    const match = COVERAGE_FILE_PATTERN.exec(name)
    if (match && match[1]) {
      const n = parseInt(match[1], 10)
      if (n > max) max = n
    }
  }
  return `code-coverage${max + 1}.yml`
}

interface CodeCoverageSectionProps {
  workflowFiles: WorkflowFile[]
  newWorkflowBaseUrl: string
  configureDocsUrl: string
  settingsGroupContainerClassName: string
  settingRowClassName: string
  coverageAgentEnabled?: boolean
  onGenerateWithAI?: () => void
  isGeneratingWithAI?: boolean
  statusBanner?: ReactNode
}

export function CodeCoverageSection({
  workflowFiles,
  newWorkflowBaseUrl,
  configureDocsUrl,
  settingsGroupContainerClassName,
  settingRowClassName,
  coverageAgentEnabled,
  onGenerateWithAI,
  isGeneratingWithAI,
  statusBanner,
}: CodeCoverageSectionProps) {
  const [dialogOpen, setDialogOpen] = useState(false)
  const newWorkflowUrl = `${newWorkflowBaseUrl}?${new URLSearchParams({filename: `.github/workflows/${getNextCoverageFilename(workflowFiles)}`}).toString()}`
  const coverageFiles = workflowFiles.filter(isCoverageFile).sort((a, b) => {
    const aNum = parseInt(COVERAGE_FILE_PATTERN.exec(basename(a.editUrl))?.[1] ?? '0', 10)
    const bNum = parseInt(COVERAGE_FILE_PATTERN.exec(basename(b.editUrl))?.[1] ?? '0', 10)
    return aNum - bNum
  })
  const highestFile = getHighestCoverageFile(workflowFiles)
  const hasCoverageFiles = coverageFiles.length > 0
  const hasWorkflowFiles = workflowFiles.length > 0
  const buttonLabel = highestFile ? basename(highestFile.name) : 'Setup'

  return (
    <div className="tmp-mb-3">
      <Heading as="h3" className="h3 mb-1">
        Code coverage analysis
      </Heading>
      <div className="color-fg-muted tmp-mb-2 text-small">
        Scans test code coverage for your repository and generates a report on every push and pull to the default
        branch.
      </div>
      {statusBanner != null && <div className="tmp-mb-3">{statusBanner}</div>}
      <div className={settingsGroupContainerClassName}>
        <div className={settingRowClassName}>
          <div className="mr-auto">
            <span className="text-bold d-block">Configure workflow file</span>
            <span className="text-small color-fg-muted d-block">
              Enable code coverage analysis with a YAML workflow file.{' '}
              <Link href={configureDocsUrl} inline target="_blank" rel="noopener noreferrer">
                Learn how to configure code coverage
              </Link>
              .
            </span>
          </div>
          {isGeneratingWithAI ? (
            <Button disabled leadingVisual={<Spinner size="small" />}>
              {hasCoverageFiles ? buttonLabel : 'Setup'}
            </Button>
          ) : hasCoverageFiles ? (
            <ActionMenu>
              <ActionMenu.Button>{buttonLabel}</ActionMenu.Button>
              <ActionMenu.Overlay width="medium">
                <ActionList>
                  <ActionList.Group>
                    <ActionList.GroupHeading>Edit existing</ActionList.GroupHeading>
                    {coverageFiles.map(file => (
                      <ActionList.LinkItem
                        key={file.editUrl}
                        href={file.editUrl}
                        target="_blank"
                        rel="noopener noreferrer"
                      >
                        <ActionList.LeadingVisual>
                          <FileCodeIcon />
                        </ActionList.LeadingVisual>
                        {basename(file.name)}
                      </ActionList.LinkItem>
                    ))}
                  </ActionList.Group>
                  <ActionList.Divider />
                  {coverageAgentEnabled && (
                    <ActionList.Item onSelect={onGenerateWithAI}>
                      <ActionList.LeadingVisual>
                        <CopilotIcon />
                      </ActionList.LeadingVisual>
                      Generate workflow with AI
                    </ActionList.Item>
                  )}
                  <ActionList.Item onSelect={() => setDialogOpen(true)}>
                    <ActionList.LeadingVisual>
                      <WorkflowIcon />
                    </ActionList.LeadingVisual>
                    Manually create workflow
                  </ActionList.Item>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          ) : coverageAgentEnabled ? (
            <ActionMenu>
              <ActionMenu.Button>Setup</ActionMenu.Button>
              <ActionMenu.Overlay width="medium">
                <ActionList>
                  <ActionList.Item onSelect={onGenerateWithAI}>
                    <ActionList.LeadingVisual>
                      <CopilotIcon />
                    </ActionList.LeadingVisual>
                    Generate workflow with AI
                    <ActionList.Description variant="block">
                      Generate a workflow file with code coverage support. A pull request will be opened to review
                      changes.
                    </ActionList.Description>
                  </ActionList.Item>
                  <ActionList.Divider />
                  <ActionList.Item onSelect={() => setDialogOpen(true)}>
                    <ActionList.LeadingVisual>
                      <WorkflowIcon />
                    </ActionList.LeadingVisual>
                    Manually create workflow
                  </ActionList.Item>
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
          ) : hasWorkflowFiles ? (
            <Button onClick={() => setDialogOpen(true)}>Setup</Button>
          ) : (
            <Button as="a" href={newWorkflowUrl} target="_blank" rel="noopener noreferrer">
              Setup
            </Button>
          )}
        </div>
      </div>
      <CodeCoverageWorkflowDialog
        open={dialogOpen}
        onClose={() => setDialogOpen(false)}
        existingWorkflowFiles={workflowFiles}
        newWorkflowUrl={newWorkflowUrl}
      />
    </div>
  )
}
